actions.script:
const side = lineSide === 'old' ? 'old' : 'new'
const number = lineNumber ? Number(lineNumber) : null
let lineText = null
if (!parentCommEventId && path && number) {
    const changes = ec.service.sync().name('ironstone.projects.CodeServices.get#MergeRequestChanges').parameters({mergeRequestId: mergeRequestId || ''}).call()?.changes
    const file = Array.from(changes?.fileList || []).find((one) => one.path === path)
    for (const hunk of Array.from(file?.hunkList || [])) for (const line of Array.from(hunk.lineList || []))
        if ((side === 'old' ? line.oldNo : line.newNo) === number) lineText = line.text
    if (lineText == null) ec.message.addError(ec.resource.expand('Line ${number} is not in the diff of ${path}', '', {number, path}))
}
if (!ec.message.hasError()) {
    const made = ec.service.sync().name('ironstone.projects.CodeServices.comment#MergeRequest').parameters({mergeRequestId: mergeRequestId || '', body: body || '',
        path: parentCommEventId ? null : (path || null), oldLine: !parentCommEventId && side === 'old' ? number : null,
        newLine: !parentCommEventId && side === 'new' ? number : null, lineText: lineText, parentCommEventId: parentCommEventId || null}).call()
    // a comment on a merge request with a public conversation may be held for review
    if (!ec.message.hasError()) ec.message.addMessage(made?.held ? ec.l10n.localize('Your comment is held for review: it shows here once a moderator approves it')
        : ec.l10n.localize('Comment added'), made?.held ? 'info' : 'success')
}

// the thread must be of this merge request (as Changes.xml's resolveThread)
const anchor = communicationEventId ? ec.service.sync().name('mantle.work.GitServices.get#ReviewThreads').parameters({mergeRequestId: mergeRequestId || ''}).call()
        ?.threadList?.find((thread) => thread.communicationEventId === communicationEventId) : null
if (!ec.message.hasError() && !anchor) ec.message.addError(ec.resource.expand('Review thread ${communicationEventId} not found', '', {communicationEventId}))
if (!ec.message.hasError()) ec.service.sync().name('mantle.work.GitServices.resolve#ReviewThread').parameters({communicationEventId: communicationEventId,
    resolved: String(resolved) !== 'false'}).call()
if (!ec.message.hasError()) ec.message.addMessage(ec.l10n.localize(String(resolved) !== 'false' ? 'Thread resolved' : 'Thread reopened'), 'success')

fileList = []; threadList = []; diffRows = []; changesFound = false
if (!recordFound) return
const L = (text) => ec.l10n.localize(text)
const out = ec.service.sync().name('ironstone.projects.CodeServices.get#MergeRequestChanges').parameters({mergeRequestId: mergeRequestId || ''}).call() || {}
ec.message.clearErrors()
changesFound = !!out.found
if (!changesFound) return
const changes = out.changes
const files = Array.from(changes.fileList || [])
const shown = files.find((file) => file.path === path) || files[0] || null
shownPath = shown ? shown.path : null
fileList = files.map((file) => ({path: file.path, changeLabel: file.changeLabel, countText: '+' + file.insertions + ' -' + file.deletions,
    threadCount: Array.from(changes.threadList || []).filter((thread) => thread.path === file.path).length,
    shownText: shown && file.path === shown.path ? L('shown') : ''}))
// the shown file's diff: a row a hunk header, then its lines (the text as data); at most 3000 lines
diffTitle = shown ? shown.path + (shown.oldPath && shown.oldPath !== shown.path ? ' (' + L('from') + ' ' + shown.oldPath + ')' : '') : ''
diffNote = shown ? (shown.binary ? L('A binary file: no diff to show.') : shown.tooLarge ? L('Too large to show here.') : '') : ''
for (const hunk of Array.from(shown?.hunkList || [])) {
    if (diffRows.length >= 3000) break
    diffRows.push({oldNo: '', newNo: '', lineText: '@@ -' + hunk.oldStart + ',' + hunk.oldLines + ' +' + hunk.newStart + ',' + hunk.newLines + ' @@'})
    for (const line of Array.from(hunk.lineList || [])) {
        if (diffRows.length >= 3000) break
        const mark = line.tag === 'insert' || line.tag === 'add' || line.tag === '+' ? '+' : line.tag === 'delete' || line.tag === 'remove' || line.tag === '-' ? '-' : ' '
        diffRows.push({oldNo: line.oldNo == null ? '' : String(line.oldNo), newNo: line.newNo == null ? '' : String(line.newNo), lineText: mark + ' ' + line.text})
    }
}
canComment = !!changes.canComment && !clientUser
// a post's body is html (a public conversation's): its text, for the terminal
const plain = (html) => String(html || '').replace(/<\/(p|div|li|pre|h[1-6]|blockquote|tr)>|<br\s*\/{0,1}>/gi, '\n').replace(/<[^>]*>/g, '')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;|&#x27;/gi, "'").replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
    .replace(/\n{3,}/g, '\n\n').trim()
threadList = Array.from(changes.threadList || []).map((thread) => ({communicationEventId: thread.communicationEventId, filePath: thread.path,
    where: thread.path + ':' + (thread.newLine ?? thread.oldLine ?? ''), resolved: !!thread.resolved,
    stateText: [thread.resolved ? L('Resolved') : L('Open'), thread.outdated ? L('outdated') : ''].filter((part) => part).join(', '),
    lineText: thread.lineText || '', commentsText: Array.from(thread.commentList || []).map((comment) => comment.authorName + ': ' + (comment.bodyFormat === 'html' ? plain(comment.body) : comment.body)).join('\n'),
    mergeRequestId: mergeRequestId}))
threadOptions = threadList.map((thread) => ({key: thread.communicationEventId, text: thread.where + ' · ' + thread.stateText}))
commentValue = {mergeRequestId: mergeRequestId, path: shownPath, lineSide: 'new'}
replyValue = {mergeRequestId: mergeRequestId, path: shownPath}
summaryText = fileList.length + ' ' + L('files') + ' · +' + (changes.insertions || 0) + ' -' + (changes.deletions || 0)
